+}
+
+const HEALTH_ATTACHMENT_PATTERN =
+  /^[ \t]*await[ \t]+([A-Za-z_$][\w$]*)\.withHealthCheck\((?:"((?:\\.|[^"\\])*)"|'((?:\\.|[^'\\])*)')\);[ \t]*$/gm;
