+const APP_REGISTRATION_PATTERN =
+  /^[ \t]*apps\.set\((?:"((?:\\.|[^"\\])*)"|'((?:\\.|[^'\\])*)'),[ \t]*([A-Za-z_$][\w$]*)\);[ \t]*$/gm;
