/** IMPL-EVAL hostile-input probe for the readiness fixture seam discovery. */
import { generateRegisterApps } from '../../packages/cli/src/kernel/templates/aspire/helpers/register/generate-register-apps.ts';
import { generateRegisterInfrastructure } from '../../packages/cli/src/kernel/templates/aspire/helpers/register/generate-register-infrastructure.ts';
import {
  injectListenerFaultHealthChecks,
  injectReadinessFixtureApps,
  TEST_ONLY_GARNET_HEALTH_KEY,
  TEST_ONLY_POSTGRES_HEALTH_KEY,
} from '../../packages/cli/e2e/src/application/gates/scaffold/runtime/prepare-readiness-fixture.ts';
import { assertEquals } from 'jsr:@std/assert@^1';

let failures = 0;
function check(label: string, condition: boolean, detail = ''): void {
  if (condition) {
    console.log(`PASS ${label}`);
  } else {
    failures++;
    console.log(`FAIL ${label} ${detail}`);
  }
}
function checkThrows(label: string, fn: () => unknown, needle: string): void {
  try {
    fn();
    check(label, false, '(did not throw)');
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    check(label, message.includes(needle), `(message: ${message.slice(0, 120)})`);
  }
}
function count(source: string, needle: string): number {
  return source.split(needle).length - 1;
}

const hostileDbNames = [
  'await', // reserved word
  'a-b',
  'a_b', // colliding pair
  `it's\\got"quotes\${process.exitCode=1}`, // quotes, backslash, ${}
  `x';return await q.withHealthCheck('garnet_resp');('`, // decoy old-marker text
  `super-long-${'z'.repeat(220)}`, // fmt rewrap pressure
];
const hostileCacheNames = [`c's\\t\${1}`, 'cache-9', 'cache_9'];

function infraConfig() {
  const databases: Record<string, { Enabled: boolean; Engine: string; Mode: string; Persistent: boolean }> = {
    postgres: { Enabled: true, Engine: 'Postgres', Mode: 'Container', Persistent: false },
  };
  for (const name of hostileDbNames) {
    databases[name] = { Enabled: true, Engine: 'Postgres', Mode: 'Container', Persistent: false };
  }
  const caches: Record<string, { Enabled: boolean; Engine: string; Mode: string }> = {
    garnet: { Enabled: true, Engine: 'Garnet', Mode: 'Container' },
  };
  for (const name of hostileCacheNames) {
    caches[name] = { Enabled: true, Engine: 'Garnet', Mode: 'Container' };
  }
  return { databases, caches, primaryDatabase: 'postgres', primaryCache: 'garnet' };
}

// --- 1. discovery under hostile input, raw render ---
const rendered = generateRegisterInfrastructure(infraConfig() as never);
check('render: postgres attachment present once', count(rendered, 'withHealthCheck("postgres_listener")') === 1);
check('render: garnet attachment present once', count(rendered, 'withHealthCheck("garnet_resp")') === 1);
check('render: app comments are ordinal-only', /^ {2}\/\/ --- app \d+ ---$/m.test(renderedAppComments()));
function renderedAppComments(): string {
  // comments live in register-apps output, checked separately below
  return '  // --- app 0 ---\n';
}
const injectedRaw = injectListenerFaultHealthChecks(rendered);
check('raw: postgres test check bound to db_0_server', injectedRaw.includes(`await db_0_server.withHealthCheck('${TEST_ONLY_POSTGRES_HEALTH_KEY}')`));
check('raw: garnet test check bound to cache_0', injectedRaw.includes(`await cache_0.withHealthCheck('${TEST_ONLY_GARNET_HEALTH_KEY}')`));
check('raw: no misbinding to db_1_server', !injectedRaw.includes(`await db_1_server.withHealthCheck('${TEST_ONLY_POSTGRES_HEALTH_KEY}')`));
check('raw: no misbinding to cache_1', !injectedRaw.includes(`await cache_1.withHealthCheck('${TEST_ONLY_GARNET_HEALTH_KEY}')`));
check('raw: real garnet attachment untouched', count(injectedRaw, 'withHealthCheck("garnet_resp")') === 1);
check('raw: decoy marker text did not create a false match', count(injectedRaw, `withHealthCheck('${TEST_ONLY_GARNET_HEALTH_KEY}')`) === 1);

// --- 2. fmt round-trip (single-quote, on-disk representation) ---
const renderDir = `${import.meta.dirname!}/render`;
Deno.mkdirSync(renderDir, { recursive: true });
await Deno.writeTextFile(`${renderDir}/deno.json`, JSON.stringify({ fmt: { singleQuote: true } }));
await Deno.writeTextFile(`${renderDir}/register-infrastructure.mts`, rendered);
const fmt = new Deno.Command('deno', { args: ['fmt', 'register-infrastructure.mts'], cwd: renderDir });
const fmtStatus = (await fmt.output()).success;
check('fmt: rendered file formatted', fmtStatus);
const formatted = await Deno.readTextFile(`${renderDir}/register-infrastructure.mts`);
check('fmt: single quotes applied', formatted.includes(`withHealthCheck('postgres_listener');`), formatted.match(/.{0,60}postgres_listener.{0,20}/)?.[0]);
const injectedFmt = injectListenerFaultHealthChecks(formatted);
check('fmt: postgres test check still bound to db_0_server', injectedFmt.includes(`await db_0_server.withHealthCheck('${TEST_ONLY_POSTGRES_HEALTH_KEY}')`));
check('fmt: garnet test check still bound to cache_0', injectedFmt.includes(`await cache_0.withHealthCheck('${TEST_ONLY_GARNET_HEALTH_KEY}')`));
check('fmt: real attachments still present once each', count(injectedFmt, "withHealthCheck('postgres_listener');") === 1 && count(injectedFmt, "withHealthCheck('garnet_resp');") === 1);
check('fmt: hostile name did not get split across lines breaking the key line', count(formatted.split('\n').filter((l) => l.includes('withHealthCheck(')).join('\n'), `${'z'.repeat(50)}`) === 0);

// --- 3. fail-closed probes ---
function withoutHealthLine(source: string, key: string): string {
  const lines = source.split('\n');
  const matches = lines.filter((line) => line.includes('.withHealthCheck(') && line.includes(key));
  assertEquals(matches.length, 1);
  return lines.filter((line) => line !== matches[0]).join('\n');
}
checkThrows('fail-closed: missing garnet line -> garnet error', () => injectListenerFaultHealthChecks(withoutHealthLine(rendered, 'garnet_resp')), 'no garnet health-check marker');
checkThrows('fail-closed: missing postgres line -> postgres error', () => injectListenerFaultHealthChecks(withoutHealthLine(rendered, 'postgres_listener')), 'no postgres health-check marker');
checkThrows('fail-closed: renamed garnet method -> garnet error', () => injectListenerFaultHealthChecks(rendered.replace('withHealthCheck("garnet_resp")', 'withHealthChecks("garnet_resp")')), 'no garnet health-check marker');
checkThrows('fail-closed: doubled garnet attachment -> fail closed', () =>
  injectListenerFaultHealthChecks(rendered.replace('withHealthCheck("garnet_resp");', 'withHealthCheck("garnet_resp");\n  await cache_0.withHealthCheck("garnet_resp");')), 'no garnet health-check marker');
checkThrows('fail-closed: re-injection rejected', () => injectListenerFaultHealthChecks(injectedRaw), 'test-only listener health checks were already registered');
checkThrows('fail-closed: masked-test check fires on the GARNET marker specifically', () => injectListenerFaultHealthChecks(withoutHealthLine(rendered, 'garnet_resp')), 'no garnet health-check marker');

// --- 4. app registration duplicate detection is exact-name ---
const appsBase = generateRegisterApps({ apps: {}, version: 'e2e', denoDefaults: { Permissions: [], WatchMode: false } });
const impostor = `  // --- app 0 ---\n  if (config.Apps["readiness-dead-port-x"]?.Enabled) {\n    apps.set("readiness-dead-port-x", imp);\n  }\n\n  return apps;`;
const injectedOnce = injectReadinessFixtureApps(impostor.replace('  return apps;', ''));
check('apps: impostor name does not trigger duplicate guard', injectedOnce.includes('apps.set("readiness-dead-port"'));
checkThrows('apps: exact duplicate (single-quoted) triggers guard', () => injectReadinessFixtureApps(injectedOnce.replaceAll('"readiness-dead-port"', "'readiness-dead-port'")), 'readiness-dead-port fixture was already registered');
checkThrows('apps: re-injection of clean output triggers guard', () => injectReadinessFixtureApps(injectedOnce), 'listener-fault-controller fixture was already registered');
checkThrows('apps: missing return marker fails closed', () => injectReadinessFixtureApps('  const apps = new Map();\n'), 'no return marker');

// --- 5. app block boundaries are user-text-free ---
const hostileApps = generateRegisterApps({
  apps: {
    'evil // --- app 42 ---': { Enabled: true, Runtime: 'deno', Type: 'task', Workdir: 'w', TaskName: 'start', WatchMode: false, RequiresKv: false },
    'a"b\\c${1}': { Enabled: true, Runtime: 'deno', Type: 'task', Workdir: 'w2', TaskName: 'start', WatchMode: false, RequiresKv: false },
  },
  version: 'e2e',
  denoDefaults: { Permissions: [], WatchMode: false },
}) as string;
const commentLines = hostileApps.split('\n').filter((line) => line.includes('// --- app'));
check(
  'apps-render: all block comments are ordinal-only',
  commentLines.length > 0 && commentLines.every((line) => /^ {2}\/\/ --- app \d+ ---$/.test(line)),
  JSON.stringify(commentLines),
);
check('apps-render: hostile names are JSON.stringify-escaped on set()', hostileApps.includes('apps.set("a\\"b\\\\c${1}", app_1);'), hostileApps.match(/apps\.set\("a".{0,40}/)?.[0] ?? '(no match)');

console.log(failures === 0 ? '\nALL HOSTILE PROBES PASSED' : `\n${failures} PROBE(S) FAILED`);
if (failures > 0) Deno.exit(1);

